<template>
  <form @submit="formSubmit">
    <div class="offcanvas offcanvas-end" tabindex="-1" id="form-offcanvas" aria-labelledby="form-offcanvasLabel">
      <FormHeader :currentId="currentId" :editTitle="editTitle" :createTitle="createTitle"></FormHeader>
      <div class="offcanvas-body">
        <InputField class="col-md-12" type="text" :is-required="true" :label="$t('title')" placeholder="Enter the title"
          v-model="title" :error-message="errors['title']" :error-messages="errorMessages['title']"></InputField>

        <InputField class="col-md-12" type="textarea" :is-required="true" :label="$t('description')"
          placeholder="Enter the description" v-model="description" :error-message="errors['description']"
          :error-messages="errorMessages['description']"></InputField>

        <div class="form-group">
          <div class="d-flex justify-content-between align-items-center">
            <label class="form-label" for="category-status">{{ $t('service.lbl_status') }}</label>
            <div class="form-check form-switch">
              <input class="form-check-input" :value="status" :true-value="1" :false-value="0" :checked="status"
                name="status" id="category-status" type="checkbox" v-model="status" />
            </div>
          </div>
        </div>

        <!-- <InputField class="col-md-12" type="datetime-local" :is-required="true" :label="$t('promotion.start_datetime')" placeholder="" v-model="start_date_time" :error-message="errors['start_date_time']" :error-messages="errorMessages['start_date_time']"></InputField>
        <InputField class="col-md-12" type="datetime-local" :is-required="true" :label="$t('promotion.end_datetime')" placeholder="" v-model="end_date_time" :error-message="errors['end_date_time']" :error-messages="errorMessages['end_date_time']"></InputField> -->
        <!-- <div class="row">
        </div>-->

        <!-- <div v-for="field in customefield" :key="field.id">
          <FormElement v-model="custom_fields_data" :name="field.name" :label="field.label" :type="field.type"
            :required="field.required" :options="field.value" :field_id="field.id"></FormElement>
        </div> -->
      </div>
      <FormFooter :IS_SUBMITED="IS_SUBMITED"></FormFooter>
    </div>
  </form>
</template>

<script setup>
import { ref, onMounted, computed } from 'vue';
import { useField, useForm } from 'vee-validate'
import { EDIT_URL, STORE_URL, UPDATE_URL} from '../constant/therapy.js'
import InputField from '@/vue/components/form-elements/InputField.vue'
import { useModuleId, useRequest, useOnOffcanvasHide } from '@/helpers/hooks/useCrudOpration'
// import { buildMultiSelectObject } from '@/helpers/utilities'
import * as yup from 'yup'
import FormHeader from '@/vue/components/form-elements/FormHeader.vue'
import FormFooter from '@/vue/components/form-elements/FormFooter.vue'
// import FormElement from '@/helpers/custom-field/FormElement.vue'


// props
defineProps({
  createTitle: { type: String, default: '' },
  editTitle: { type: String, default: '' },
  customefield: { type: Array, default: () => [] }
})

const { getRequest, storeRequest, updateRequest, listingRequest } = useRequest()


const singleSelectOption = ref({
  closeOnSelect: true,
  searchable: true
})


const getTimeZoneList = () => {
  listingRequest({ url: TIME_ZONE_LIST, data: { type: type } }).then((res) => {
    time_zone.value.options = buildMultiSelectObject(res.results, {
      value: 'id',
      label: 'text'
    })
  })
}


// Edit Form Or Create Form
const currentId = useModuleId(() => {
  if (currentId.value > 0) {
    getRequest({ url: EDIT_URL, id: currentId.value }).then((res) => {
      if (res.status) {
        setFormData(res.data)
        ISREADONLY.value = true
      }
    })
  } else {
    resetForm()
    setFormData(defaultData())
  }
})

const resetMyForm = () => resetForm();

useOnOffcanvasHide('form-offcanvas', () => {
  setFormData(defaultData());
  resetMyForm();
});

// Default FORM DATA
const defaultData = () => {
  errorMessages.value = {}
  ISREADONLY.value = false
  return {
    title: '',
    description: '',
    status: 1,
  }
}

//  Reset Form
const setFormData = (data) => {
  resetForm({
    values: {
      title: data.title,
      description: data.description,
      status: data.status,
    }
  })
}

// Reload Datatable, SnackBar Message, Alert, Offcanvas Close
const reset_datatable_close_offcanvas = (res) => {
  IS_SUBMITED.value = false
  if (res.status) {
    window.successSnackbar(res.message)
    renderedDataTable.ajax.reload(null, false)
    bootstrap.Offcanvas.getInstance('#form-offcanvas').hide()
    setFormData(defaultData())
  } else {
    window.errorSnackbar(res.message)
    errorMessages.value = res.all_message
  }
}

// Validations
const validationSchema = yup.object({
  title: yup.string().required('Title is a required'),
  description: yup.string().required('Description is a required'),
})

const { handleSubmit, errors, resetForm } = useForm({
  validationSchema
})

const { value: title } = useField('title')
const { value: description } = useField('description')
const { value: status } = useField('status')
const errorMessages = ref({})

// const typeOptions = [
//   { label: 'Percent', value: 'percent' },
//   { label: 'Fixed', value: 'fixed' }
// ]

// const couponOptions = [
//   { label: 'Custom', value: 'custom' },
//   { label: 'bulk', value: 'bulk' }
// ]

onMounted(() => {
  setFormData(defaultData())
})

const ISREADONLY = ref(false)
// Form Submit
const IS_SUBMITED = ref(false)
const formSubmit = handleSubmit((values) => {
  if (IS_SUBMITED.value) return false
  values.custom_fields_data = JSON.stringify(values.custom_fields_data)
  if (currentId.value > 0) {
    updateRequest({ url: UPDATE_URL, id: currentId.value, body: values }).then((res) => reset_datatable_close_offcanvas(res))
  } else {
    storeRequest({ url: STORE_URL, body: values }).then((res) => reset_datatable_close_offcanvas(res))
  }
})
</script>
